export async function submitTask(ref: string): Promise<void> {
	assertWritable('submit task');

	const response = await fetch(`${API_BASE}/api/tasks/${ref}/submit`, {
		method: 'POST',
		headers: getProjectHeaders()
	});
	if (!response.ok) {
		await handleResponseError(response);
	}
}

